def cmp_semver(a, b):
    def parse(version_str):
        # Remove build metadata (everything after +)
        if '+' in version_str:
            version_str = version_str.split('+', 1)[0]

        # Split core version and pre-release
        # Core version is M.m.p, integers. Pre-release starts with '-' after patch.
        hyphen_idx = version_str.find('-')

        if hyphen_idx != -1:
            core_str = version_str[:hyphen_idx]
            pre_str = version_str[hyphen_idx+1:]
            pre_identifiers = pre_str.split('.')
        else:
            core_str = version_str
            pre_identifiers = []

        try:
            core_parts = [int(x) for x in core_str.split('.')]
        except ValueError:
            core_parts = []

        return core_parts, pre_identifiers

    def get_pre_release_key(s):
        # Returns tuple (type, value) for comparison.
        # Type 0: Numeric (sorts before Alphanumeric Type 1).
        # Type 1: Alphanumeric (String).

        if s.isdecimal():
            # Check for leading zeros (SemVer numeric identifiers MUST NOT have them)
            if len(s) > 1 and s[0] == '0':
                # Leading zero makes it an alphanumeric identifier string
                return (1, s)
            else:
                # Valid numeric identifier
                return (0, int(s))
        else:
            # Alphanumeric identifier
            return (1, s)

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    # 1. Compare Core Version (Major, Minor, Patch)
    max_core = max(len(core_a), len(core_b))
    for i in range(max_core):
        val_a = core_a[i] if i < len(core_a) else 0
        val_b = core_b[i] if i < len(core_b) else 0

        if val_a < val_b:
            return -1
        if val_a > val_b:
            return 1

    # 2. Compare Pre-release
    has_pre_a = len(pre_a) > 0
    has_pre_b = len(pre_b) > 0

    # A version WITH a pre-release sorts BEFORE the same version without one.
    if has_pre_a and not has_pre_b:
        return -1
    if not has_pre_a and has_pre_b:
        return 1

    # Compare identifiers if both have pre-release (or neither)
    max_pre_len = max(len(pre_a), len(pre_b))

    for k in range(max_pre_len):
        if k >= len(pre_a):
            return -1  # a is shorter, sorts before
        if k >= len(pre_b):
            return 1   # b is shorter, a sorts after

        key_a = get_pre_release_key(pre_a[k])
        key_b = get_pre_release_key(pre_b[k])

        if key_a < key_b:
            return -1
        if key_a > key_b:
            return 1

    return 0
```

