import re

def gitignore_match(pattern, path):
    if not pattern:
        return False

    trailing_slash = pattern.endswith('/')
    if trailing_slash:
        pattern = pattern[:-1]
        if not path.endswith('/'):
            return False

    pat = pattern
    anchored = False
    if pat.startswith('/'):
        pat = pat[1:]
        anchored = True
    elif '/' in pat:
        anchored = True
    else:
        anchored = False

    regex_parts = []
    i = 0
    n = len(pat)
    while i < n:
        c = pat[i]
        if c == '*':
            if i + 1 < n and pat[i+1] == '*':
                if i + 2 < n and pat[i+2] == '/':
                    regex_parts.append('(?:.*/)?')
                    i += 3
                else:
                    regex_parts.append('.*')
                    i += 2
            else:
                regex_parts.append('[^/]*')
                i += 1
        elif c == '?':
            regex_parts.append('[^/]')
            i += 1
        elif c == '[':
            j = pat.find(']', i+1)
            if j == -1:
                regex_parts.append(re.escape(c))
                i += 1
            else:
                class_content = pat[i+1:j]
                if class_content and class_content[0] == '!':
                    class_content = '^' + class_content[1:]
                regex_parts.append('[' + class_content + ']')
                i = j + 1
        elif c == '/':
            regex_parts.append('/')
            i += 1
        else:
            regex_parts.append(re.escape(c))
            i += 1

    regex_str = '^' + ''.join(regex_parts) if anchored else r'(?:(?:^|/)(?:[^/]+/)*)?' + ''.join(regex_parts)
    regex_str += '$'

    return bool(re.match(regex_str, path))
