def parse_range(header, size):
    if not header or not header.lower().startswith("bytes="):
        return None
    raw = header[6:].strip()
    if not raw:
        return None

    ranges = []
    parts = [p.strip() for p in raw.split(",")]

    for part in parts:
        if "-" in part:
            hyphen_idx = part.index("-")
            start_str = part[:hyphen_idx]
            end_str = part[hyphen_idx+1:]

            if start_str == "" and end_str == "":
                return None
            elif start_str == "":
                try:
                    suffix_len = int(end_str)
                except ValueError:
                    return None
                if suffix_len < 0:
                    return None
                if suffix_len > size:
                    start, end = 0, size - 1
                else:
                    start, end = size - suffix_len, size - 1
            else:
                try:
                    start = int(start_str)
                except ValueError:
                    return None
                if start < 0:
                    return None
                if end_str == "":
                    end = size - 1
                else:
                    try:
                        end = int(end_str)
                    except ValueError:
                        return None
                end = min(end, size - 1)
                if start > size - 1:
                    continue
                if start > end:
                    continue
                ranges.append((start, end))
        else:
            return None

    return ranges if ranges else None
```

