def unified_diff(a, b, context=3):
    m, n = len(a), len(b)
    if m == 0 and n == 0:
        return []

    # LCS DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            if a[i] == b[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i][j+1], dp[i+1][j])

    # Backtrack to find matching indices
    matches = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i-1] == b[j-1]:
            matches.append((i-1, j-1))
            i -= 1
            j -= 1
        elif dp[i-1][j] >= dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    matches.reverse()

    # Generate opcodes from matches
    opcodes = []
    a_idx, b_idx = 0, 0
    for mi, mj in matches:
        if a_idx < mi or b_idx < mj:
            opcodes.append(('replace', a_idx, mi, b_idx, mj))
        elif a_idx < mi:
            opcodes.append(('delete', a_idx, mi, b_idx, b_idx))
        elif b_idx < mj:
            opcodes.append(('insert', a_idx, a_idx, b_idx, mj))
        else:
            opcodes.append(('equal', a_idx, mi+1, b_idx, mj+1))
        a_idx = mi + 1
        b_idx = mj + 1
    if a_idx < m:
        opcodes.append(('delete', a_idx, m, b_idx, b_idx))
    elif b_idx < n:
        opcodes.append(('insert', a_idx, a_idx, b_idx, n))

    # Flatten opcodes into output_lines with source indices
    output_lines = []
    for tag, i1, i2, j1, j2 in opcodes:
        if tag == 'equal':
            for i in range(i1, i2):
                output_lines.append({'prefix': ' ', 'a_idx': i, 'b_idx': j1 + (i-i1)})
        elif tag == 'delete':
            for i in range(i1, i2):
                output_lines.append({'prefix': '-', 'a_idx': i, 'b_idx': None})
        elif tag == 'insert':
            for j in range(j1, j2):
                output_lines.append({'prefix': '+', 'a_idx': None, 'b_idx': j})
        elif tag == 'replace':
            for i in range(i1, i2):
                output_lines.append({'prefix': '-', 'a_idx': i, 'b_idx': None})
            for j in range(j1, j2):
                output_lines.append({'prefix': '+', 'a_idx': None, 'b_idx': j})

    change_indices = [k for k, line in enumerate(output_lines) if line['prefix'] in ('-', '+')]
    if not change_indices:
        return []

    # Determine hunk ranges with context
    ranges = []
    for idx in change_indices:
        ranges.append((max(0, idx - context), min(len(output_lines), idx + context + 1)))

    # Merge overlapping/adjacent ranges
    merged = []
    for s, e in ranges:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))

    # Build result
    result = []
    for s, e in merged:
        hunk_lines = output_lines[s:e]
        a_count = sum(1 for line in hunk_lines if line['a_idx'] is not None)
        b_count = sum(1 for line in hunk_lines if line['b_idx'] is not None)

        fa = next((line['a_idx'] for line in hunk_lines if line['a_idx'] is not None), None)
        fb = next((line['b_idx'] for line in hunk_lines if line['b_idx'] is not None), None)
        a_start = (fa + 1) if fa is not None else 0
        b_start = (fb + 1) if fb is not None else 0

        result.append(f"@@ -{a_start},{a_count} +{b_start},{b_count} @@")
        for line in hunk_lines:
            if line['a_idx'] is not None:
                result.append(line['prefix'] + a[line['a_idx']])
            else:
                result.append(line['prefix'] + b[line['b_idx']])

    return result
