from collections import OrderedDict

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.key_to_freq = {}
        self.freq_map = {}

    def _update(self, key):
        freq = self.key_to_freq[key]
        val = self.freq_map[freq].pop(key)
        if not self.freq_map[freq]:
            if freq == self.min_freq:
                self.min_freq += 1
        self.key_to_freq[key] += 1
        new_freq = self.key_to_freq[key]
        if new_freq not in self.freq_map:
            self.freq_map[new_freq] = OrderedDict()
        self.freq_map[new_freq][key] = val

    def get(self, key):
        if key not in self.key_to_freq:
            return -1
        self._update(key)
        return self.freq_map[self.key_to_freq[key]][key]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.key_to_freq:
            self._update(key)
            self.freq_map[self.key_to_freq[key]][key] = value
        else:
            if self.size == self.capacity:
                evict_key, _ = self.freq_map[self.min_freq].popitem(last=False)
                del self.key_to_freq[evict_key]
                self.size -= 1
            self.key_to_freq[key] = 1
            if 1 not in self.freq_map:
                self.freq_map[1] = OrderedDict()
            self.freq_map[1][key] = value
            self.size += 1
            self.min_freq = 1

