import heapq

def topk(stream, k):
    if k <= 0:
        return []
    heap = []
    for i, (val, label) in enumerate(stream):
        item = (val, -i, label)
        if len(heap) < k:
            heapq.heappush(heap, item)
        elif item > heap[0]:
            heapq.heapreplace(heap, item)
    return [(v, l) for v, _, l in sorted(heap, key=lambda x: (x[0], x[1]), reverse=True)]
