    hi = []  # Min-heap (store x)

    lo_lazy = {}
    hi_lazy = {}

    lo_size = 0
    hi_size = 0

    res = []

    def clean_lo():
        while lo:
            val = -lo[0]
            lazy_count = lo_lazy.get(val, 0)
            if lazy_count > 0:
                heapq.heappop(lo)
                if lazy_count > 1:
                    lo_lazy[val] = lazy_count - 1
                else:
                    del lo_lazy[val]
            else:
                break

    def clean_hi():
        while hi:
            val = hi[0]
            lazy_count = hi_lazy.get(val, 0)
            if lazy_count > 0:
                heapq.heappop(hi)
                if lazy_count > 1:
                    hi_lazy[val] = lazy_count - 1
                else:
                    del hi_lazy[val]
            else:
                break

    def rebalance():
        total = lo_size + hi_size
        target_lo = total // 2
        target_hi = total - target_lo

        while lo_size > target_lo:
            clean_lo()
            if not lo:
                break
            val = -heapq.heappop(lo)
            lo_size -= 1
            heapq.heappush(hi, val)
            hi_size += 1

        while hi_size > target_hi:
