            if not hi:
                break
            val = heapq.heappop(hi)
            hi_size -= 1
            heapq.heappush(lo, -val)
            lo_size += 1

    for i, x in enumerate(a):
        if i >= k:
            out_val = a[i - k]
            clean_lo()
            clean_hi()

