class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.sz = [1] * n
        self.history = []
        self._components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False
        if self.sz[a] < self.sz[b]:
            a, b = b, a
        self.history.append((b, a, self.sz[a]))
        self.parent[b] = a
        self.sz[a] += self.sz[b]
        self._components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            b, a, old_sz = self.history.pop()
            self.parent[b] = b
            self.sz[a] = old_sz
            self._components += 1

    def components(self):
        return self._components
