    memo = {}
    def _copy(o):
        oid = id(o)
        if oid in memo:
            return memo[oid]

        t = type(o)
        if t in (bool, int, float, str, type(None)):
            return o

        if t is list:
            res = []
            memo[oid] = res
            for item in o:
                res.append(_copy(item))
            return res
        elif t is dict:
            res = {}
            memo[oid] = res
            for k, v in o.items():
                res[_copy(k)] = _copy(v)
            return res
        elif t is set:
            res = set()
            memo[oid] = res
            for item in o:
                res.add(_copy(item))
            return res
        elif t is tuple:
            res = tuple(_copy(item) for item in o)
            memo[oid] = res
            return res
        else:
            raise TypeError(f"Unsupported type: {t}")

