def to_base(n, alphabet):
    base = len(alphabet)
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    digits = []
    while n:
        digits.append(alphabet[n % base])
        n //= base
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))

def from_base(s, alphabet):
    if not s:
        raise ValueError("String cannot be empty")
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet cannot be empty")

    negative = s[0] == '-'
    if negative:
        s = s[1:]
        if not s:
            raise ValueError("Invalid string")

    char_to_val = {ch: i for i, ch in enumerate(alphabet)}
    val = 0
    for ch in s:
        if ch not in char_to_val:
            raise ValueError("Character not in alphabet")
        val = val * base + char_to_val[ch]
    return -val if negative else val

