import heapq

def merge_sorted(iterables):
    iters = [iter(it) for it in iterables]
    heap = []
    for i, it in enumerate(iters):
        try:
            heap.append((next(it), i))
        except StopIteration:
            pass
    heapq.heapify(heap)
    while heap:
        val, i = heapq.heappop(heap)
        yield val
        try:
            next_val = next(iters[i])
            heapq.heappush(heap, (next_val, i))
        except StopIteration:
            pass
