def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    best = {src: (0, 0, (src,))}
    pq = [(0, 0, src, (src,))]

    while pq:
        c, e, u, path = heapq.heappop(pq)

        best_info = best[u]
        if (c, e) > (best_info[0], best_info[1]) or ((c, e) == (best_info[0], best_info[1]) and path > best_info[2]):
            continue

        if u == dst:
            return (c, list(path))

