        tok = tokens[i]
        if tok.lstrip('-').isdigit():
            return float(tok) if '.' in tok else int(tok), i + 1
        if re.match(r'^[A-Za-z]+[0-9]+$', tok):
            return ('CELL', tok), i + 1
        raise ValueError(f"Invalid token: {tok}")

