  if (seen === undefined) seen = new Map();
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;

  let cache = seen.get(a);
  if (!cache) {
    cache = new WeakMap();
    seen.set(a, cache);
  }
  if (cache.has(b)) return cache.get(b);

  cache.set(b, false);

  const type = Object.prototype.toString.call(a);
  if (type !== Object.prototype.toString.call(b)) {
    cache.set(b, false);
    return false;
  }

  let result = false;

  if (type === '[object Date]') {
    result = Object.is(a.getTime(), b.getTime());
  } else if (type === '[object RegExp]') {
    result = a.source === b.source && a.flags === b.flags;
  } else if (type === '[object Map]') {
    if (a.size !== b.size) {
      cache.set(b, false);
      return false;
    }
    for (const [key, valA] of a.entries()) {
      if (!b.has(key)) {
        cache.set(b, false);
        return false;
      }
      if (!deepEqual(valA, b.get(key), seen)) {
        cache.set(b, false);
        return false;
      }
    }
    result = true;
  } else if (type === '[object Set]') {
    if (a.size !== b.size) {
      cache.set(b, false);
      return false;
    }
    const bVals = [...b.values()];
    const matched = new Array(b.size).fill(false);
    for (const valA of a.values()) {
      let idx = -1;
      for (let i = 0; i < bVals.length; i++) {
        if (matched[i]) continue;
        if (deepEqual(valA, bVals[i], seen)) {
          idx = i;
          break;
        }
      }
      if (idx === -1) {
        cache.set(b, false);
        return false;
      }
      matched[idx] = true;
    }
    result = true;
