function debounce(fn, wait, options = {}) {
  let timer = null;
  let lastResult = undefined;
  let lastThis = null;
  let lastArgs = null;
  let lastCallTime = 0;

  const leading = options.leading === true;
  const trailing = options.trailing !== false;

  function run() {
    const result = fn.apply(lastThis, lastArgs);
    lastResult = result;
    lastCallTime = Date.now();
  }

  function debounced(...args) {
    lastThis = this;
    lastArgs = args;
    const now = Date.now();

    if (timer) {
      clearTimeout(timer);
      timer = null;
    }

    if (leading && now - lastCallTime > wait) {
      run();
    } else if (trailing) {
      timer = setTimeout(run, wait);
    }

    return lastResult;
  }

  debounced.cancel = function() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  debounced.flush = function() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
      run();
    }
    return lastResult;
  };

  return debounced;
}

module.exports = debounce;
