function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iters = iterables.map(it => 
    typeof it[Symbol.iterator] === 'function' ? it[Symbol.iterator]() : it
  );

  const active = new Array(iterables.length).fill(true);
  let remaining = iterables.length;

  while (remaining > 0) {
    const row = [];
    for (let i = 0; i < iterables.length; i++) {
      if (active[i]) {
        const { value, done } = iters[i].next();
        if (done) {
          active[i] = false;
          remaining--;
        }
        row.push(done ? fill : value);
      } else {
        row.push(fill);
      }
    }
    yield row;
  }
}

