function parseQuery(qs) {
  if (!qs || qs === '?') return {};
  qs = qs.replace(/^\?/, '');
  const result = {};
  const pairs = qs.split('&');
  const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));

  for (const pair of pairs) {
    if (!pair) continue;
    const eqIdx = pair.indexOf('=');
    let key, val;
    if (eqIdx === -1) {
      key = pair;
      val = '';
    } else {
      key = pair.slice(0, eqIdx);
      val = pair.slice(eqIdx + 1);
    }
    key = decode(key);
    val = decode(val);

    const path = [];
    const re = /([^[\]]+)|\[(\d*)\]/g;
    let match;
    while ((match = re.exec(key)) !== null) {
      path.push(match[1] !== undefined ? match[1] : (match[2] === '' ? '' : parseInt(match[2], 10)));
    }

    let curr = result;
    for (let i = 0; i < path.length - 1; i++) {
      const p = path[i];
      const next = path[i+1];
      if (curr[p] === undefined || curr[p] === null || typeof curr[p] !== 'object') {
        curr[p] = (typeof next === 'number' || next === '') ? [] : {};
      }
      curr = curr[p];
    }

    const finalKey = path[path.length - 1];
    if (curr[finalKey] !== undefined) {
      if (!Array.isArray(curr[finalKey])) {
        curr[finalKey] = [curr[finalKey]];
      }
      curr[finalKey].push(val);
    } else {
      curr[finalKey] = val;
    }
  }
  return result;
}

function buildQuery(obj, prefix = '') {
  let parts = [];
  const keys = Array.isArray(obj)
    ? Object.keys(obj).sort((a, b) => a - b)
    : Object.keys(obj).sort();
  const encodeKey = (k) => encodeURIComponent(k).replace(/%5B/g, '[').replace(/%5D/g, ']');

  for (const key of keys) {
    const value = obj[key];
    const currentKey = prefix ? `${prefix}[${key}]` : key;

    if (value !== null && typeof value === 'object') {
      if (Array.isArray(value)) {
        const isNumeric = keys.every((k, i) => k === String(i));
        if (isNumeric) {
          value.forEach((v, i) => {
            parts = parts.concat(buildQuery({ [i]: v }, currentKey));
          });
        } else {
          value.forEach((v, i) => {
            parts = parts.concat(buildQuery({ '': v }, currentKey));
          });
        }
      } else {
        parts = parts.concat(buildQuery(value, currentKey));
      }
    } else {
      parts.push(`${encodeKey(currentKey)}=${encodeURIComponent(String(value !== undefined ? value : ''))}`);
    }
  }
  return parts;
}

module.exports = {
  parseQuery,
  buildQuery: (obj) => buildQuery(obj).join('&')
};
