function toposortTasks(tasks) {
  const inDegree = {};
  const dependents = {};
  const taskNames = Object.keys(tasks);

  for (const name of taskNames) {
    const deps = tasks[name].deps || [];
    inDegree[name] = deps.length;
    for (const dep of deps) {
      if (!tasks[dep]) {
        throw new Error(`Missing dependency: ${dep}`);
      }
      if (!dependents[dep]) dependents[dep] = [];
      dependents[dep].push(name);
    }
  }

  const results = {};
  const queue = taskNames.filter(name => inDegree[name] === 0);
  const errors = [];
  let remaining = taskNames.length;

  async function processBatch() {
    if (queue.length === 0 || remaining === 0) return;

    const batch = [];
    while (queue.length > 0) {
      batch.push(queue.shift());
    }

    const settledResults = await Promise.allSettled(
      batch.map(name => tasks[name].run(results))
    );

    for (let i = 0; i < batch.length; i++) {
      const name = batch[i];
      const res = settledResults[i];
      remaining--;

      if (res.status === 'fulfilled') {
        results[name] = res.value;
      } else {
        if (errors.length === 0) errors.push(res.reason);
      }

      if (dependents[name]) {
        for (const depName of dependents[name]) {
          inDegree[depName]--;
          if (inDegree[depName] === 0) {
            queue.push(depName);
          }
        }
      }
    }

    if (remaining > 0) {
      await processBatch();
    }
  }

  return (async () => {
    await processBatch();
    if (errors.length > 0) {
      throw errors[0];
    }
    return results;
  })();
}

module.exports = { toposortTasks };
