export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, ((p: any) => void)[]>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners.has(k)) {
      this.listeners.set(k, []);
    }
    const handlers = this.listeners.get(k)!;
    handlers.push(fn as (payload: any) => void);
    return () => {
      const idx = handlers.indexOf(fn as (payload: any) => void);
      if (idx !== -1) handlers.splice(idx, 1);
    };
  }

  emit<K extends keyof E>(k: K): void;
  emit<K extends keyof E>(k: K, payload: [E[K]] extends [void] ? never : E[K]): void;
  emit<K extends keyof E>(k: K, payload?: unknown): void {
    const handlers = this.listeners.get(k);
    if (!handlers) return;
    for (const fn of handlers) {
      (fn as any)(payload);
    }
  }
}
