export function pick<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Pick<T, K> {
  const res: Pick<T, K> = {} as Pick<T, K>;
  for (const key of keys) {
    if (Object.hasOwn(obj, key)) {
      (res as any)[key] = obj[key];
    }
  }
  return res;
}

export function omit<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Omit<T, K> {
  const allKeys = Object.keys(obj) as (keyof T)[];
  const keptKeys = allKeys.filter(key => !keys.includes(key as string));
  return pick(obj, keptKeys as unknown as K[]) as Omit<T, K>;
}
