export type Result<T, E> = { readonly kind: 'ok'; readonly value: T } | { readonly kind: 'err'; readonly error: E };

export function ok<T>(value: T): Result<T, never> {
  return { kind: 'ok', value };
}

export function err<E>(error: E): Result<never, E> {
  return { kind: 'err', error };
}

export function isOk<T, E>(r: Result<T, E>): r is { kind: 'ok'; value: T } {
  return r.kind === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is { kind: 'err'; error: E } {
  return r.kind === 'err';
}

export function map<T, E, F>(r: Result<T, E>, fn: (value: T) => F): Result<F, E> {
  return isOk(r) ? ok(fn(r.value)) : err(r.error);
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  return isOk(r) ? r.value : fallback;
}
